<style>
:root{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Noto Sans JP",sans-serif;color:#172033;background:#f5f7fb}*{box-sizing:border-box}body{margin:0}header{background:#fff;border-bottom:1px solid #dfe5ee;padding:14px 20px;display:flex;align-items:center;justify-content:space-between;gap:12px;position:sticky;top:0;z-index:10}h1{font-size:21px;margin:2px 0}header small{color:#667085}a{color:#2563eb}.wrap{max-width:1380px;margin:18px auto;padding:0 14px}.panel{background:#fff;border:1px solid #dfe5ee;border-radius:12px;padding:14px;margin-bottom:14px;box-shadow:0 2px 8px #12203a0a}.controls{display:flex;flex-wrap:wrap;gap:10px;align-items:end}.controls label{display:grid;gap:5px;font-size:13px;font-weight:700}.controls input,.controls select,.rate-form input,.rate-form select{min-height:38px;border:1px solid #cfd7e3;border-radius:8px;padding:7px 9px;background:#fff}button{min-height:38px;border:1px solid #c7d0de;border-radius:8px;background:#fff;padding:7px 12px;font-weight:700;cursor:pointer}.primary{background:#2457d6;color:#fff;border-color:#2457d6}.danger{color:#b42318}.summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:10px}.card{border:1px solid #e1e7ef;border-radius:10px;padding:12px}.card .value{font-size:25px;font-weight:800;margin-top:3px}.muted{color:#667085}.category-cards{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.chip{background:#f4f7fb;border:1px solid #dbe3ee;border-radius:999px;padding:6px 10px;font-size:13px}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap}th,td{border-bottom:1px solid #e5e9f0;padding:8px 9px;text-align:left;font-size:13px}th{background:#f8fafc;position:sticky;top:0}td.num,th.num{text-align:right}.missing{background:#fff3cd;color:#7a4b00;font-weight:700}.rate-note{font-size:13px;color:#667085;margin:7px 0 12px}.status{font-size:13px;margin-left:8px}.rate-input{width:110px;min-height:34px;border:1px solid #cfd7e3;border-radius:7px;padding:5px 8px;text-align:right}.savebar{display:flex;gap:10px;align-items:center;margin:10px 0;position:sticky;top:72px;background:#fff;padding:8px 0;z-index:3}.paircount{font-size:13px;color:#667085}.right{margin-left:auto}.teacher-summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px}.teacher-card{border:1px solid #e1e7ef;border-radius:10px;padding:12px}.teacher-card b{font-size:15px}.teacher-card .money{font-size:22px;font-weight:800;margin-top:4px}.detail-box summary{cursor:pointer;font-weight:800;font-size:16px;padding:2px 0 10px}.detail-box[open] summary{margin-bottom:6px}@media(max-width:760px){header{align-items:flex-start;flex-direction:column}.controls>*{flex:1 1 140px}.right{margin-left:0}.savebar{top:104px}}
.lesson-link{background:transparent;border:0;padding:4px 0;text-align:left;color:#2457b3;text-decoration:underline;text-underline-offset:3px;white-space:normal}.lesson-link:hover{color:#103e95}.payroll-dialog{border:0;border-radius:14px;padding:0;width:min(800px,94vw);max-height:88dvh;color:#172033}.payroll-dialog::backdrop{background:#172d4670}.payroll-dialog-inner{display:flex;flex-direction:column;max-height:88dvh}.payroll-dialog header{position:static;flex:none}.payroll-dialog h2{font-size:18px;margin:0}.payroll-dialog-body{padding:16px;overflow:auto}.payroll-lesson{display:flex;gap:16px;justify-content:space-between;padding:12px 0;border-top:1px solid #dfe5ee;font-size:14px}.payroll-lesson p{margin:5px 0;color:#526477}.payroll-lesson a{display:block;padding:8px 0}.payroll-lesson>div{min-width:0;overflow-wrap:anywhere}@media(max-width:600px){.payroll-lesson{flex-direction:column;gap:0}.payroll-dialog header{flex-direction:row}}
